SELECT  FROM im_chain_entry
 WHERE chain_id = #{chainId} AND status = 'ACTIVE' AND position > #{after}
 ORDER BY position LIMIT #{limit}

SELECT id, channel_id AS channelId, member_id AS memberId, DATE_FORMAT(checkin_date, '%Y-%m-%d') AS checkinDate, source, streak,
       checked_at AS checkedAt
  FROM im_channel_checkin WHERE channel_id = #{channelId} AND member_id = #{memberId} AND checkin_date = #{date}

SELECT DATE_FORMAT(checkin_date, '%Y-%m-%d') FROM im_channel_checkin
 WHERE channel_id = #{channelId} AND member_id = #{memberId} AND checkin_date <= #{date}
 ORDER BY checkin_date DESC LIMIT 30

SELECT c.member_id AS memberId, COUNT(1) AS days, m.nickname AS nickname, m.avatar AS avatar
  FROM im_channel_checkin c LEFT JOIN ums_member m ON m.id = c.member_id
 WHERE c.channel_id = #{channelId} AND c.checkin_date > DATE_SUB(#{date}, INTERVAL 30 DAY) AND c.checkin_date <= #{date}
 GROUP BY c.member_id, m.nickname, m.avatar
 ORDER BY days DESC, c.member_id ASC LIMIT #{limit}
